When filtering or mapping arrays of objects, use defensive guards (such as checking if the element is a valid object) to ignore nullish or malformed elements instead of throwing a TypeError. This ensures the function fails closed gracefully if any element is malformed.

```javascript
function provenanceRefsForAssertion(assertion) {
  const refs = [];
  for (const evidenceRef of Array.isArray(assertion?.evidence_bundle?.evidence_refs)
    ? assertion.evidence_bundle.evidence_refs
    : []) {
    if (isObject(evidenceRef)) {
      refs.push({
        ref_kind: 'evidence_ref',
        evidence_ref_id: evidenceRef.evidence_ref_id ?? null,
        artifact_path: evidenceRef.artifact_path ?? null,
        pointer: evidenceRef.pointer ?? null,
      });
    }
  }
  for (const span of Array.isArray(assertion?.source_spans) ? assertion.source_spans : []) {
    if (isObject(span)) {
      refs.push({
        ref_kind: 'source_span',
        span_id: span.span_id ?? null,
        artifact_path: span.artifact_path ?? null,
        pointer: span.pointer ?? null,
      });
    }
  }
  const provenance = assertion?.evidence_bundle?.provenance_refs ?? {};
  for (const ref of Array.isArray(provenance.source_shard_assertion_refs)
    ? provenance.source_shard_assertion_refs
    : []) {
    if (isObject(ref)) {
      refs.push({
        ref_kind: 'source_shard_assertion_ref',
        path: ref.path ?? null,
        json_pointer: ref.json_pointer ?? null,
        assertion_id: ref.assertion_id ?? null,
      });
    }
  }
  return refs;
}
