+    if (claim?.claim_kind === 'semantic_assertion_fact') {
+      if (status === 'accepted') {
+        if (!claimHasProvenance(claim)) errors.push('accepted_fact_missing_provenance');
+      }
+      if (status === 'provisional_safe') {
+        if (!provisionalDowngradeMachineCheckPasses(claim) ||
+          semanticFactCertaintyOverclaims(claim)) {
+          errors.push('provisional_safe_requires_tentative_wording');
+        }
+      }
+    }
