+      const overclaims = claim.evidence_basis === 'semantic_kg_only' ||
+        !hasString(claim.learner_attempt_evidence_ref);
+      const certain = posture.statement_posture === 'asserted_fact' ||
+        posture.certainty_level === 'certain' ||
+        posture.certainty_level === 'high';
+      if (overclaims && certain) errors.push('mastery_overclaim_blocked');
