+      bad_fail_fixture_count: badFixtures.filter((item) => (
+        item.actual_validation_status === 'fail'
+      )).length,
+      unexpected_pass_count: badFixtures.filter((item) => (
+        item.actual_validation_status === 'pass'
+      )).length,
+      unexpected_fail_count: cleanFixtures.filter((item) => (
+        item.actual_validation_status === 'fail'
+      )).length,
+    },
